/**
 * Revealing the secret key of a classic keypair wallet.
 *
 * WHY THIS EXISTS
 * ---------------
 * Some phones cannot create a passkey at all — a Redmi Note 11 5G returns
 * `createCredentialAsync no provider dependencies found` from
 * `react-native-passkeys`, with no setting on the device that exposes a
 * credential provider. For those users the classic keypair wallet (a plain
 * Stellar G-account generated by `lib/testnetWallet.ts`) is the only wallet
 * they can make. Its signing key is a real Stellar secret, held in exactly one
 * place: the device keychain under `SecureKey.signerSecret`.
 *
 * The encrypted backup in `lib/backup.ts` cannot save that wallet. It
 * deliberately strips private key material — `assertNoSecretMaterial` is the
 * last line of defence, and it stays that way (see the test in
 * `lib/__tests__/backup.test.ts`). That is correct for a file people drop in a
 * cloud drive, but it means that before this module existed the secret had no
 * way out of the app at all: uninstall the app, lose the wallet. The only copy
 * of a wallet's key was on the one device that could be lost.
 *
 * WHAT THIS MODULE DOES
 * ---------------------
 * It decides *whether* a secret may be shown, and proves it is the right
 * secret, before anything is displayed. The UI is a thin wrapper over
 * {@link resolveSecretExport} and {@link requireDeviceUnlock}.
 *
 * MONEY-SAFETY RULES (this wallet holds real funds on mainnet)
 * ------------------------------------------------------------
 * 1. **A smart wallet never gets here.** Its key lives in a passkey and never
 *    leaves it, so there is no secret to export; `lib/walletStore.ts` still
 *    holds a `signerSecret`, but that is the *fee-payer* — a PRF-derived
 *    implementation detail, not the wallet. The stored address starts with `C`,
 *    and the secret is not even read.
 * 2. **A secret is revealed only when it provably IS the wallet.** The stored
 *    address must be a valid G-address AND must equal the public key derived
 *    from the stored secret. Anything else — a fee-payer key under a contract
 *    address, a half-written wallet, a corrupt entry — refuses. This is also
 *    what makes the round trip trustworthy: importing the revealed secret
 *    derives exactly this address by construction, because that is the check
 *    that let the reveal happen.
 * 3. **Nothing is written anywhere.** No log, no AsyncStorage key, no backup
 *    envelope. The secret is returned to the caller and displayed; it is never
 *    persisted by this module, and it must never be handed to
 *    `encryptBackup`/`assertNoSecretMaterial`'s output path.
 * 4. **The gate is a real one.** `requirePasskey()` no-ops for exactly the
 *    wallets this module serves (no passkey exists on them), so it cannot be
 *    the lock. {@link requireDeviceUnlock} prompts the device biometric or
 *    passcode instead — the same factor `app/lock.tsx` uses.
 */

import { Keypair, StrKey } from '@stellar/stellar-sdk';
import * as LocalAuthentication from 'expo-local-authentication';

import { getSignerSecret, getWalletAddress } from './walletStore';

// ── Wallet kind ─────────────────────────────────────────────────────────────────

/**
 * What kind of wallet the stored address describes.
 *
 * `'smart'` is decided by the same `startsWith('C')` test the spend path uses
 * (`lib/spendAsset.ts`), and that is load-bearing: if this module and the
 * spending path disagreed about which wallet they were looking at, the screen
 * could offer to export a secret for a wallet whose money is actually held by a
 * passkey. Both sides must classify the same address the same way.
 */
export type WalletKind = 'smart' | 'keypair' | 'none' | 'unknown';

export function walletKind(address: string | null | undefined): WalletKind {
  if (!address) return 'none';
  if (address.startsWith('C')) return 'smart';
  // A classic keypair wallet is a signed Stellar account: a valid ed25519
  // public key. Anything that decodes is a candidate for the reveal; anything
  // that does not is not a wallet we will print a key for.
  try {
    StrKey.decodeEd25519PublicKey(address);
    return 'keypair';
  } catch {
    return 'unknown';
  }
}

// ── Resolution ──────────────────────────────────────────────────────────────────

/**
 * Every outcome of inspecting this device's wallet, discriminated by `status`.
 *
 * `revealable` is the only state that carries a secret, and only after
 * {@link resolveSecretExport} has proved the secret derives the stored address.
 */
export type SecretExportState =
  /** Nothing on this network — no wallet to export. */
  | { status: 'no-wallet' }
  /**
   * A passkey smart wallet (`C…` address). Its key never leaves the passkey,
   * so no export is offered and the stored signer secret — the fee-payer — is
   * deliberately not read.
   */
  | { status: 'smart-wallet'; address: string }
  /** The stored address is neither a contract nor a decodable G-account. */
  | { status: 'unknown-address'; address: string }
  /** A G-address wallet, but this device holds no key for it. */
  | { status: 'no-secret'; address: string }
  /**
   * A G-address wallet whose stored secret does not derive that address.
   * Showing it would be worse than useless: the user would import a key that
   * controls a different account and conclude their wallet was gone.
   */
  | { status: 'secret-mismatch'; address: string }
  /** Proven: `secret` is the signing key of `address`. */
  | { status: 'revealable'; address: string; secret: string };

/**
 * Inspect the active network's wallet and decide what may be revealed.
 *
 * Reads fresh on every call (no caching): the whole point is to be right about
 * the wallet that is on the device *now*, and a cached state could outlive a
 * wallet reset or a network switch — the two moments where being wrong is most
 * expensive.
 */
export async function resolveSecretExport(): Promise<SecretExportState> {
  const address = await getWalletAddress();
  if (!address) return { status: 'no-wallet' };

  const kind = walletKind(address);
  if (kind === 'smart') return { status: 'smart-wallet', address };
  if (kind !== 'keypair') return { status: 'unknown-address', address };

  const secret = await getSignerSecret();
  if (!secret) return { status: 'no-secret', address };

  // The proof. `Keypair.fromSecret` throws on a malformed seed, and a well-formed
  // seed for a different account simply will not match — both refuse.
  let derived: string;
  try {
    derived = Keypair.fromSecret(secret).publicKey();
  } catch {
    return { status: 'secret-mismatch', address };
  }
  if (derived !== address) return { status: 'secret-mismatch', address };

  return { status: 'revealable', address, secret };
}

// ── The lock ────────────────────────────────────────────────────────────────────

/** Outcome of the device-authentication gate. */
export type UnlockOutcome =
  /** The user passed the device biometric or passcode. */
  | 'unlocked'
  /** The prompt was dismissed. Nothing was shown. */
  | 'cancelled'
  /** The system refused, or the factor did not match. */
  | 'failed'
  /**
   * This device has no screen lock or biometric enrolled, so there is no lock
   * to go behind.
   *
   * `app/lock.tsx` lets such a user through, and it is right to: an idle lock
   * that nobody can answer is a door that will not open, and passing it loses
   * nothing. A secret reveal is the opposite case — displaying a key behind a
   * gate with nothing on the other side would tell the user their key was
   * protected when it was never protected at all. So this is a refusal, with
   * the reason stated.
   */
  | 'not-protected';

/**
 * The slice of `expo-local-authentication` the gate actually uses, declared
 * structurally so a test can hand in a fake device without mocking a native
 * module. The real namespace satisfies it.
 */
export type DeviceAuthenticator = {
  /** Read from here rather than the imported module, so a fake's NONE is honoured. */
  SecurityLevel: { NONE: number };
  getEnrolledLevelAsync: () => Promise<number>;
  authenticateAsync: (options: {
    promptMessage: string;
    cancelLabel: string;
    disableDeviceFallback: boolean;
  }) => Promise<{ success: boolean; error?: string }>;
};

export type UnlockOptions = {
  /** Message shown in the system prompt; say what is about to be unlocked. */
  promptMessage: string;
  /** Injectable for tests. Defaults to `expo-local-authentication`. */
  authenticate?: DeviceAuthenticator;
};

/**
 * Ask the device to prove the person holding the phone is its owner.
 *
 * This is the app lock's own factor — `expo-local-authentication`, the same
 * module `app/lock.tsx` and `hooks/useInactivityLock.ts` use — because
 * `requirePasskey()` is a no-op for precisely the wallets this screen serves:
 * a keypair wallet exists because this device could not make a passkey, so
 * there is no passkey to assert with. Gating the reveal on it would have
 * looked like a gate and been a formality.
 */
export async function requireDeviceUnlock(options: UnlockOptions): Promise<UnlockOutcome> {
  const auth = options.authenticate ?? LocalAuthentication;

  let level: number;
  try {
    level = await auth.getEnrolledLevelAsync();
  } catch {
    // Unreadable status is not permission to skip the lock.
    return 'failed';
  }
  if (level === auth.SecurityLevel.NONE) return 'not-protected';

  try {
    const result = await auth.authenticateAsync({
      promptMessage: options.promptMessage,
      cancelLabel: 'Cancel',
      // A PIN/passcode fallback has to stay available — a phone whose sensor
      // stopped recognising its owner is still the owner's phone, and locking
      // someone out of their own key is not safety.
      disableDeviceFallback: false,
    });
    if (result.success) return 'unlocked';
    // `error` is a platform string; user cancellation is the one case worth
    // naming, because "cancelled" and "denied" read very differently.
    const code = String(result.error ?? '').toLowerCase();
    return code.includes('cancel') ? 'cancelled' : 'failed';
  } catch {
    return 'failed';
  }
}

/** Plain-language reason a reveal was refused, for the screen to show. */
export const REFUSAL_COPY: Record<
  Exclude<SecretExportState, { status: 'revealable' }>['status'],
  { title: string; body: string }
> = {
  'no-wallet': {
    title: 'No wallet on this device',
    body: 'Create or import a wallet first. There is nothing to reveal yet.',
  },
  'smart-wallet': {
    title: 'This wallet has no secret key to reveal',
    body:
      'It is a smart wallet, built on a passkey. Its key was created inside the passkey and ' +
      'never left it, so there is nothing here to export — and that is the point. Back it up ' +
      'with an encrypted backup, or recover it with the same passkey on another device.',
  },
  'unknown-address': {
    title: 'This wallet’s address is not recognised',
    body:
      'The address stored for this network is neither a smart-wallet contract nor a classic ' +
      'account, so no key can be safely shown for it. Nothing has been changed; check the ' +
      'network you are on.',
  },
  'no-secret': {
    title: 'No signing key on this device',
    body:
      'This wallet’s address is stored here, but its secret key is not — so it cannot be ' +
      'revealed, and it cannot sign. If you have the secret from somewhere else, import it.',
  },
  'secret-mismatch': {
    title: 'The stored key does not match this wallet',
    body:
      'The signing key on this device does not derive this wallet’s address, so it is not this ' +
      'wallet’s key and it will not be shown. Revealing it would hand you a key to a different ' +
      'account. Nothing has been changed.',
  },
};
